                    f"/api/v1/cases/{case_id}/capture/{role}/originals/{index}"
                    for index in range(len(originals))
                ],
                "document_urls": [
                    f"/api/v1/cases/{case_id}/capture/{role}/documents/{index}"
                    for index in range(len(documents))
                ],
            }
