                self.capture_raw_html_path(case_id, role)
            except HTTPException:
                galleries[role]["raw_html_url"] = None
            else:
                galleries[role]["raw_html_url"] = (
                    f"/api/v1/cases/{case_id}/capture/{role}/raw-html"
