def _bundle_browser_capture_artifacts(
    *,
    bundle: Path,
    artifacts_dir: Path,
    bundled_artifacts: dict[str, Path],
    role_captures: dict[str, ScreenshotCapture | None],
    legal_screenshot_statuses: dict[str, dict[str, str]],
    protection_type: str | None,
    requested_url: str,
    captured_url: str,
    browser_run_root: str | None,
) -> tuple[str, dict[str, dict[str, Any]], Path]:
    entries: list[dict[str, Any]] = []
    galleries: dict[str, dict[str, Any]] = {}
    metric_documents: list[dict[str, Any]] = []
    copied_directories: dict[str, str] = {}
    page_artifacts: dict[str, dict[str, Any]] = {}
    for role, capture in role_captures.items():
        if capture is None or not getattr(capture, "artifact_directory", None):
            continue
        source_root = Path(capture.artifact_directory).resolve()
        source_key = str(source_root)
        effective_role = copied_directories.get(source_key, role)
        if source_key not in copied_directories:
            role_root = artifacts_dir / "roles" / role
            shutil.copytree(source_root, role_root)
            copied_directories[source_key] = role
            for path in sorted(role_root.rglob("*")):
                if not path.is_file():
                    continue
                relative = path.relative_to(bundle).as_posix()
                relative_in_role = path.relative_to(role_root).as_posix()
                label = f"capture_{role}_{relative_in_role}"
                bundled_artifacts[label] = path
                entries.append(
                    {
                        "role": role,
                        "path": relative,
                        "sha256": sha256_file(path),
                        "size_bytes": path.stat().st_size,
                        "kind": (
                            "derived_preview"
                            if path.name == "screenshot-preview.webp" else "original"
                        ),
                        "derived_from": (
                            f"artifacts/roles/{role}/screenshot-index.json"
                            if path.name == "screenshot-preview.webp" else None
                        ),
                    }
                )
            resource_metrics = role_root / "resource-metrics.json"
            if resource_metrics.is_file():
                metric_documents.append(
                    json.loads(resource_metrics.read_text(encoding="utf-8"))
                )
        role_root = artifacts_dir / "roles" / effective_role
        screenshot_index = role_root / "screenshot-index.json"
        page_record = _page_artifact_record(bundle, role_root, role, effective_role)
        page_artifacts[role] = page_record
        if screenshot_index.is_file():
            index_data = json.loads(screenshot_index.read_text(encoding="utf-8"))
            galleries[role] = {
                "source_role": effective_role,
                "preview": f"artifacts/roles/{effective_role}/screenshot-preview.webp",
                "index": f"artifacts/roles/{effective_role}/screenshot-index.json",
                "mode": index_data.get("mode"),
                "capture_completeness": index_data.get("capture_completeness"),
                "tiles": [
                    f"artifacts/roles/{effective_role}/{item['path']}"
                    for item in index_data.get("tiles", [])
                ],
                "originals": (
                    [f"artifacts/roles/{effective_role}/screenshot-full-page.png"]
                    if index_data.get("full_page_attempt", {}).get("path")
                    else []
                ),
                "raw_html": page_record["primary_raw_html"],
                "normalized_text": page_record["primary_normalized_text"],
                "documents": [
                    item["path"] for item in page_record["document_files"]
                ],
                "page_artifacts_complete": page_record["required_artifacts_complete"],
            }
    page_artifacts_index = artifacts_dir / "page-artifacts-index.json"
    _write_json(
        page_artifacts_index,
        {
            "version": 1,
            "scope": "jede_im_lauf_tatsaechlich_erfasste_seite",
            "pages": page_artifacts,
            "all_required_artifacts_complete": all(
                item["required_artifacts_complete"] for item in page_artifacts.values()
            ) if page_artifacts else False,
        },
    )
    bundled_artifacts["page_artifacts_index"] = page_artifacts_index
    states = [
        getattr(capture, "capture_completeness", "vollstaendig_erfasst")
        for capture in role_captures.values()
        if capture is not None
    ]
    if protection_type:
        completeness = "durch_seitenschutz_begrenzt"
    elif role_captures.get("main") is None:
        completeness = "teilweise_erfasst"
    elif "teilweise_erfasst" in states or any(
        status.get("status") in {"failed", "warning"}
        for status in legal_screenshot_statuses.values()
    ) or any(
        not item["required_artifacts_complete"] for item in page_artifacts.values()
    ):
        completeness = "teilweise_erfasst"
    else:
        completeness = "vollstaendig_erfasst"
    capture_index = artifacts_dir / "capture-index.json"
    _write_json(
        capture_index,
        {
            "version": 1,
            "capture_completeness": completeness,
            "sources": galleries,
            "artifacts": entries,
        },
    )
    bundled_artifacts["capture_index"] = capture_index
    metrics_path = artifacts_dir / "capture-metrics.json"
    _write_json(
        metrics_path,
        {
            "version": 1,
            "targets": metric_documents,
            "browser_run_root": browser_run_root,
            "warc_size_bytes": {"value": "pending", "reason": "WARC folgt."},
            "zip_size_bytes": {
                "value": "not_available",
                "reason": "ZIP wird erst beim lokalen Download erzeugt.",
            },
        },
    )
    bundled_artifacts["capture_metrics"] = metrics_path
    run_result = artifacts_dir / "run-result.json"
    _write_json(
        run_result,
        {
            "status": completeness,
            "requested_url": requested_url,
            "captured_url": captured_url,
            "protection_type": protection_type,
            "failure_phase": next(
                (
                    document.get("failure_phase")
                    for document in metric_documents
                    if document.get("failure_phase")
                ),
                None,
            ),
            "available_intermediate_artifacts": [item["path"] for item in entries],
        },
    )
    bundled_artifacts["run_result"] = run_result
    return completeness, galleries, metrics_path


def _page_artifact_record(
    bundle: Path,
    role_root: Path,
    role: str,
    source_role: str,
) -> dict[str, Any]:
    """Inventory HTML, normalized text and every image for one captured page."""
    request_path = role_root / "request.json"
    request_data = (
        failure_message: str | None = None
        screenshot: ScreenshotCapture | None = None
        context = None
        page = None
        try:
            context = self._browser.new_context(
                viewport={"width": 1440, "height": 900},
                user_agent=self.user_agent,
                locale="de-DE",
            )
            self.contexts += 1

            def route_request(route) -> None:  # noqa: ANN001
                browser_request = route.request
                resource_type = browser_request.resource_type
                request_counts[resource_type] = request_counts.get(resource_type, 0) + 1
                if browser_request.method.upper() not in {"GET", "HEAD", "OPTIONS"}:
                    blocked_requests.append({"url": browser_request.url, "reason": "method"})
                    route.abort()
                    return
                try:
                    if self.request_guard is not None:
                        self.request_guard(browser_request.url, resource_type)
                except Exception as exc:
                    blocked_requests.append({"url": browser_request.url, "reason": str(exc)})
                    route.abort()
                    return
                route.continue_()

            def record_response(response) -> None:  # noqa: ANN001
                nonlocal transferred_bytes, transferred_unknown
                try:
                    value = response.headers.get("content-length")
                    if value and value.isdigit():
                        transferred_bytes += int(value)
                    else:
                        transferred_unknown += 1
                except PlaywrightError:
                    transferred_unknown += 1

            context.route("**/*", route_request)
            page = context.new_page()
            self.pages += 1
            page.on("response", record_response)
            failure_phase = "navigation_domcontentloaded"
            navigation_started = time.perf_counter()
            response = page.goto(
                url,
                wait_until="domcontentloaded",
                timeout=int(self.timeout_seconds * 1000),
            )
            phase_durations["navigation_domcontentloaded"] = time.perf_counter() - navigation_started
            if response is None:
                raise ScreenshotCaptureError("Browsernavigation lieferte keine HTTP-Antwort.")
            failure_phase = "initialzustand_sichern"
            initial = _capture_initial_state(page, response, url)
            _write_initial_artifacts(target_root, initial)
            process_samples.append(_process_sample())
            if self.after_initial_hook is not None:
                self.after_initial_hook(page, target_root)
            phase_durations["initialzustand_sichern"] = (
                time.perf_counter() - navigation_started
                - phase_durations["navigation_domcontentloaded"]
            )
            if int(initial["status_code"]) >= 400:
                raise ScreenshotCaptureError(
                    f"Browsernavigation endete mit HTTP {initial['status_code']}."
                )

            failure_phase = "consent"
            consent = handle_consent(
                page, str(target_root / "screenshot-before-consent.png")
            )
            interactions.append(consent)
            _write_text(target_root / "dom-after-consent.html", page.content())
            _write_text(
                target_root / "visible-text-after-consent.txt", _visible_text(page)
            )
            phase_durations["consent"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())

            failure_phase = "expansion"
            legal_expansion_summary: dict[str, object] | None = None
            if role in {"agb", "privacy", "datenschutz"}:
                expansion_records = _expand_legal_controls(page)
                interactions.extend(expansion_records)
                legal_expansion_summary = _legal_expansion_summary(
                    page, expansion_records
                )
            _write_text(target_root / "dom-after-expansion.html", page.content())
            final_text = _visible_text(page)
            _write_text(target_root / "visible-text-final.txt", final_text)
            final_evidence_text = (
                _legal_container_text(page)
                if role in {"agb", "privacy", "datenschutz"}
                else final_text
            )
            expanded_blocks = [
                {
                    "target_text": str(record.get("target_text", "")),
                    "aria_controls": record.get("aria_controls"),
                    "text": str(record.get("expanded_text", "")),
                    "changed": bool(record.get("changed")),
                }
                for record in interactions
                if record.get("type") == "legal_expansion"
                and str(record.get("expanded_text", "")).strip()
            ]
            if role in {"agb", "privacy", "datenschutz"}:
                _write_json(
                    target_root / "expanded-legal-blocks.json",
                    {"blocks": expanded_blocks},
                )
            evidence_text = _merge_evidence_text(
                final_evidence_text,
                *(block["text"] for block in expanded_blocks),
            )
            normalized_text = "\n".join(
                line.strip() for line in evidence_text.splitlines() if line.strip()
            )
            visible_blocks = [line for line in evidence_text.splitlines() if line.strip()]
            included_blocks = [line for line in normalized_text.splitlines() if line.strip()]
            coverage_ratio = (
                len(included_blocks) / len(visible_blocks) if visible_blocks else 0.0
            )
            _write_text(target_root / "normalized-text.txt", normalized_text)
            _write_json(
                target_root / "clauses.json",
                {
                    "clauses": _simple_clauses(normalized_text),
                    "source": "visible-text-final_and_sequential_expansions",
                },
            )
            _write_json(
                target_root / "content-coverage.json",
                {
                    "method": "semantic_main_container_visible_text",
                    "normalized_visible_blocks": len(visible_blocks),
                    "included_blocks": len(included_blocks),
                    "coverage_ratio": coverage_ratio,
                    "omitted_blocks": [],
                    "legal_expansion": legal_expansion_summary,
                },
            )
            phase_durations["expansion"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())

            failure_phase = "screenshot"
            _wait_for_visual_capture(page, timeout_seconds=self.timeout_seconds)
            screenshot = _capture_validated_screenshots(page, target_root, interactions)
            if role in {"agb", "privacy", "datenschutz"}:
                _capture_expanded_legal_print_pdf(
                    page,
                    target_root,
                    legal_expansion_summary or {},
                    expanded_blocks,
                    normalized_text,
                )
            expansion_incomplete = bool(
                legal_expansion_summary
                and not legal_expansion_summary.get("complete", False)
            )
            if role in {"agb", "privacy", "datenschutz"} and (
                coverage_ratio < 0.98 or expansion_incomplete
            ):
                reason = (
                    f"Rechtstextabdeckung {coverage_ratio:.1%} liegt unter 98 %."
                    if coverage_ratio < 0.98
                    else "Nicht alle erkannten Rechtstext-Akkordeons konnten geöffnet werden."
                )
                screenshot = replace(
                    screenshot,
                    capture_state="page_content_truncated",
                    state_reason=reason,
                    capture_completeness="teilweise_erfasst",
                )
            phase_durations["screenshot"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())
            failure_phase = None
        except PlaywrightError as exc:
            failure_message = f"{type(exc).__name__}: {exc}"
            if not (initial and _browser_was_closed(exc)):
                raise ScreenshotCaptureError(
                    f"Browser-Abruf fehlgeschlagen in Phase {failure_phase}: {exc}"
                ) from exc
        except ScreenshotCaptureError as exc:
            failure_message = f"{type(exc).__name__}: {exc}"
            if initial is None:
                raise
        finally:
            try:
                if page is not None:
                    page.close()
            except PlaywrightError:
                pass
            finally:
                try:
                    if context is not None:
                        context.close()
                except PlaywrightError:
                    pass

        if initial is None:
            raise ScreenshotCaptureError("Kein Initialzustand konnte gesichert werden.")
        normalized_path = target_root / "normalized-text.txt"
        if not normalized_path.is_file():
            _write_text(normalized_path, _normalized_html_text(initial["dom"]))
        protection = _detect_block_page(initial["dom"])
        if protection:
            completeness = "durch_seitenschutz_begrenzt"
        elif failure_message or screenshot is None or not initial["raw_response"]:
            completeness = "teilweise_erfasst"
        else:
            completeness = screenshot.capture_completeness
        process_samples.append(_process_sample())
        rss_values = [
            int(sample["rss_bytes"])
            for sample in process_samples
            if isinstance(sample.get("rss_bytes"), int)
        ]
        handles = [
            int(sample["handles"])
            for sample in process_samples
            if isinstance(sample.get("handles"), int)
        ]
        stored_files = [path for path in target_root.rglob("*") if path.is_file()]
        metrics = {
            "duration_seconds": round(time.perf_counter() - phase_started, 6),
            "phase_durations_seconds": {
                key: round(max(0.0, value), 6) for key, value in phase_durations.items()
            },
            "python_rss_bytes": (
                {
                    "average": round(statistics.fmean(rss_values)),
                    "maximum": max(rss_values),
                    "samples": rss_values,
                }
                if rss_values
                else {"value": "not_available", "reason": "psutil lieferte keine RSS-Probe."}
            ),
            "python_cpu_time_seconds": {
                "start": {
                    "user": process_samples[0].get("cpu_user_seconds"),
                    "system": process_samples[0].get("cpu_system_seconds"),
                },
                "end": {
                    "user": process_samples[-1].get("cpu_user_seconds"),
                    "system": process_samples[-1].get("cpu_system_seconds"),
                },
            },
            "python_peak_handles_or_fds": max(handles) if handles else {
                "value": "not_available",
                "reason": "psutil lieferte keine Handle-/FD-Probe.",
            },
            "chromium_peak_rss_bytes": {
                "value": "not_available",
                "reason": "Playwright stellt unter Windows keine stabile Chromium-PID bereit.",
            },
            "requests_by_resource_type": request_counts,
            "transferred_bytes_from_content_length": transferred_bytes,
            "responses_without_content_length": transferred_unknown,
            "temporary_storage_bytes": sum(path.stat().st_size for path in stored_files),
            "raw_response_bytes": (target_root / "raw-response.bin").stat().st_size,
            "dom_initial_bytes": (target_root / "dom-initial.html").stat().st_size,
            "dom_final_bytes": (
                (target_root / "dom-after-expansion.html").stat().st_size
                if (target_root / "dom-after-expansion.html").is_file()
                else {"value": "not_available", "reason": "Browser endete vor dem Finalzustand."}
            ),
            "browser_starts": self.browser_starts,
            "contexts": self.contexts,
            "pages": self.pages,
            "failure_phase": failure_phase,
            "failure_message": failure_message,
        }
        metrics_path = target_root / "resource-metrics.json"
        _write_json(metrics_path, metrics)
        _write_json(target_root / "interactions.json", {"interactions": interactions})
        browser_metadata = {
            "erfassungsmodus": "browsergestuetzt",
            "user_agent": initial["user_agent"],
            "navigator_webdriver": initial["navigator_webdriver"],
            "automation_flags": [],
            "proxy": "keiner",
            "context": "frisch_pro_ziel_url",
            "storage_state": "keiner",
            "profilverzeichnis": "keines",
            "browser_engine": "Chromium",
            "browser_version": self._browser.version,
            "launch_args": list(self.launch_args),
            "request_count": sum(request_counts.values()),
            "document_request_count": request_counts.get("document", 0),
            "blocked_request_count": len(blocked_requests),
            "capture_artifact_directory": str(target_root),
            "capture_completeness": completeness,
            "failure_phase": failure_phase,
            "failure_message": failure_message,
        }
        _write_json(target_root / "browser-metadata.json", browser_metadata)
        headers = tuple(initial["headers"].items()) + (
            ("X-MucLegal-Capture-Mode", "browser-rendered-dom"),
        )
        fetch_result = FetchResult(
            requested_url=url,
            final_url=initial["final_url"],
            fetched_at=initial["captured_at"],
            status_code=int(initial["status_code"]),
            headers=headers,
            redirect_chain=tuple(initial["redirect_chain"]),
            body=initial["dom"].encode("utf-8"),
            decoded_html=initial["dom"],
            fetch_mode="browser_review",
            browser_metadata=browser_metadata,
        )
        return BrowserTargetCapture(
            fetch_result=fetch_result,
            screenshot=screenshot,
            artifact_directory=str(target_root),
            capture_completeness=completeness,
            failure_phase=failure_phase,
        )


def _capture_initial_state(page, response, requested_url: str) -> dict:  # noqa: ANN001
    redirect_chain: list[str] = []
    redirected_request = response.request
    while redirected_request.redirected_from is not None:
        redirect_chain.append(redirected_request.url)
        redirected_request = redirected_request.redirected_from
    redirect_chain.reverse()
    try:
        raw_response = response.body()
        raw_response_source = "playwright_document_response_body"
    except Exception as exc:
        raw_response = b""
        raw_response_source = f"not_available:{type(exc).__name__}:{exc}"
    snapshot = page.evaluate(
        """() => ({
          title: document.title,
          dom: document.documentElement?.outerHTML || '',
          visibleText: document.body?.innerText || '',
          userAgent: navigator.userAgent,
          navigatorWebdriver: navigator.webdriver,
          viewport: {width: window.innerWidth, height: window.innerHeight},
          scrollWidth: document.documentElement?.scrollWidth || 0,

item.aggregated_output:
    )
    return privacy_terms >= 2 and len(text) >= 1_500


def _bundle_browser_capture_artifacts(
    *,
    bundle: Path,
    artifacts_dir: Path,
    bundled_artifacts: dict[str, Path],
    role_captures: dict[str, ScreenshotCapture | None],
    legal_screenshot_statuses: dict[str, dict[str, str]],
    protection_type: str | None,
    requested_url: str,
    captured_url: str,
    browser_run_root: str | None,
) -> tuple[str, dict[str, dict[str, Any]], Path]:
    entries: list[dict[str, Any]] = []
    galleries: dict[str, dict[str, Any]] = {}
    metric_documents: list[dict[str, Any]] = []
    copied_directories: dict[str, str] = {}
    page_artifacts: dict[str, dict[str, Any]] = {}
    for role, capture in role_captures.items():
        if capture is None or not getattr(capture, "artifact_directory", None):
            continue
        source_root = Path(capture.artifact_directory).resolve()
        source_key = str(source_root)
        effective_role = copied_directories.get(source_key, role)
        if source_key not in copied_directories:
            role_root = artifacts_dir / "roles" / role
            shutil.copytree(source_root, role_root)
            copied_directories[source_key] = role
            for path in sorted(role_root.rglob("*")):
                if not path.is_file():
                    continue
                relative = path.relative_to(bundle).as_posix()
                relative_in_role = path.relative_to(role_root).as_posix()
                label = f"capture_{role}_{relative_in_role}"
                bundled_artifacts[label] = path
                entries.append(
                    {
                        "role": role,
                        "path": relative,
                        "sha256": sha256_file(path),
                        "size_bytes": path.stat().st_size,
                        "kind": (
                            "derived_preview"
                            if path.name == "screenshot-preview.webp" else "original"
                        ),
                        "derived_from": (
                            f"artifacts/roles/{role}/screenshot-index.json"
                            if path.name == "screenshot-preview.webp" else None
                        ),
                    }
                )
            resource_metrics = role_root / "resource-metrics.json"
            if resource_metrics.is_file():
                metric_documents.append(
                    json.loads(resource_metrics.read_text(encoding="utf-8"))
                )
        role_root = artifacts_dir / "roles" / effective_role
        screenshot_index = role_root / "screenshot-index.json"
        page_record = _page_artifact_record(bundle, role_root, role, effective_role)
        page_artifacts[role] = page_record
        if screenshot_index.is_file():
            index_data = json.loads(screenshot_index.read_text(encoding="utf-8"))
            galleries[role] = {
                "source_role": effective_role,
                "preview": f"artifacts/roles/{effective_role}/screenshot-preview.webp",
                "index": f"artifacts/roles/{effective_role}/screenshot-index.json",
                "mode": index_data.get("mode"),
                "capture_completeness": index_data.get("capture_completeness"),
                "tiles": [
                    f"artifacts/roles/{effective_role}/{item['path']}"
                    for item in index_data.get("tiles", [])
                ],
                "originals": (
                    [f"artifacts/roles/{effective_role}/screenshot-full-page.png"]
                    if index_data.get("full_page_attempt", {}).get("path")
                    else []
                ),
                "raw_html": page_record["primary_raw_html"],
                "normalized_text": page_record["primary_normalized_text"],
                "documents": [
                    item["path"] for item in page_record["document_files"]
                ],
                "page_artifacts_complete": page_record["required_artifacts_complete"],
            }
    page_artifacts_index = artifacts_dir / "page-artifacts-index.json"
    _write_json(
        page_artifacts_index,
        {
            "version": 1,
            "scope": "jede_im_lauf_tatsaechlich_erfasste_seite",
            "pages": page_artifacts,
            "all_required_artifacts_complete": all(
                item["required_artifacts_complete"] for item in page_artifacts.values()
            ) if page_artifacts else False,
        },
    )
    bundled_artifacts["page_artifacts_index"] = page_artifacts_index
    states = [
        getattr(capture, "capture_completeness", "vollstaendig_erfasst")
        for capture in role_captures.values()
        if capture is not None
    ]
    if protection_type:
        completeness = "durch_seitenschutz_begrenzt"
    elif role_captures.get("main") is None:
        completeness = "teilweise_erfasst"
    elif "teilweise_erfasst" in states or any(
        status.get("status") in {"failed", "warning"}
        for status in legal_screenshot_statuses.values()
    ) or any(
        not item["required_artifacts_complete"] for item in page_artifacts.values()
    ):
        completeness = "teilweise_erfasst"
    else:
        completeness = "vollstaendig_erfasst"
    capture_index = artifacts_dir / "capture-index.json"
    _write_json(
        capture_index,
        {
            "version": 1,
            "capture_completeness": completeness,
            "sources": galleries,
            "artifacts": entries,
        },
    )
    bundled_artifacts["capture_index"] = capture_index
    metrics_path = artifacts_dir / "capture-metrics.json"
    _write_json(
        metrics_path,
        {
            "version": 1,
            "targets": metric_documents,
            "browser_run_root": browser_run_root,
            "warc_size_bytes": {"value": "pending", "reason": "WARC folgt."},
            "zip_size_bytes": {
                "value": "not_available",
                "reason": "ZIP wird erst beim lokalen Download erzeugt.",
            },
        },
    )
    bundled_artifacts["capture_metrics"] = metrics_path
    run_result = artifacts_dir / "run-result.json"
    _write_json(
        run_result,
        {
            "status": completeness,
            "requested_url": requested_url,
            "captured_url": captured_url,
            "protection_type": protection_type,
            "failure_phase": next(
                (
                    document.get("failure_phase")
                    for document in metric_documents
                    if document.get("failure_phase")
                ),
                None,
            ),
            "available_intermediate_artifacts": [item["path"] for item in entries],
        },
    )
    bundled_artifacts["run_result"] = run_result
    return completeness, galleries, metrics_path


def _page_artifact_record(
    bundle: Path,
    role_root: Path,
    role: str,
    source_role: str,
) -> dict[str, Any]:
    """Inventory HTML, normalized text and every image for one captured page."""
    request_path = role_root / "request.json"
    request_data = (
        failure_message: str | None = None
        screenshot: ScreenshotCapture | None = None
        context = None
        page = None
        try:
            context = self._browser.new_context(
                viewport={"width": 1440, "height": 900},
                user_agent=self.user_agent,
                locale="de-DE",
            )
            self.contexts += 1

            def route_request(route) -> None:  # noqa: ANN001
                browser_request = route.request
                resource_type = browser_request.resource_type
                request_counts[resource_type] = request_counts.get(resource_type, 0) + 1
                if browser_request.method.upper() not in {"GET", "HEAD", "OPTIONS"}:
                    blocked_requests.append({"url": browser_request.url, "reason": "method"})
                    route.abort()
                    return
                try:
                    if self.request_guard is not None:
                        self.request_guard(browser_request.url, resource_type)
                except Exception as exc:
                    blocked_requests.append({"url": browser_request.url, "reason": str(exc)})
                    route.abort()
                    return
                route.continue_()

            def record_response(response) -> None:  # noqa: ANN001
                nonlocal transferred_bytes, transferred_unknown
                try:
                    value = response.headers.get("content-length")
                    if value and value.isdigit():
                        transferred_bytes += int(value)
                    else:
                        transferred_unknown += 1
                except PlaywrightError:
                    transferred_unknown += 1

            context.route("**/*", route_request)
            page = context.new_page()
            self.pages += 1
            page.on("response", record_response)
            failure_phase = "navigation_domcontentloaded"
            navigation_started = time.perf_counter()
            response = page.goto(
                url,
                wait_until="domcontentloaded",
                timeout=int(self.timeout_seconds * 1000),
            )
            phase_durations["navigation_domcontentloaded"] = time.perf_counter() - navigation_started
            if response is None:
                raise ScreenshotCaptureError("Browsernavigation lieferte keine HTTP-Antwort.")
            failure_phase = "initialzustand_sichern"
            initial = _capture_initial_state(page, response, url)
            _write_initial_artifacts(target_root, initial)
            process_samples.append(_process_sample())
            if self.after_initial_hook is not None:
                self.after_initial_hook(page, target_root)
            phase_durations["initialzustand_sichern"] = (
                time.perf_counter() - navigation_started
                - phase_durations["navigation_domcontentloaded"]
            )
            if int(initial["status_code"]) >= 400:
                raise ScreenshotCaptureError(
                    f"Browsernavigation endete mit HTTP {initial['status_code']}."
                )

            failure_phase = "consent"
            consent = handle_consent(
                page, str(target_root / "screenshot-before-consent.png")
            )
            interactions.append(consent)
            _write_text(target_root / "dom-after-consent.html", page.content())
            _write_text(
                target_root / "visible-text-after-consent.txt", _visible_text(page)
            )
            phase_durations["consent"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())

            failure_phase = "expansion"
            legal_expansion_summary: dict[str, object] | None = None
            if role in {"agb", "privacy", "datenschutz"}:
                expansion_records = _expand_legal_controls(page)
                interactions.extend(expansion_records)
                legal_expansion_summary = _legal_expansion_summary(
                    page, expansion_records
                )
            _write_text(target_root / "dom-after-expansion.html", page.content())
            final_text = _visible_text(page)
            _write_text(target_root / "visible-text-final.txt", final_text)
            final_evidence_text = (
                _legal_container_text(page)
                if role in {"agb", "privacy", "datenschutz"}
                else final_text
            )
            expanded_blocks = [
                {
                    "target_text": str(record.get("target_text", "")),
                    "aria_controls": record.get("aria_controls"),
                    "text": str(record.get("expanded_text", "")),
                    "changed": bool(record.get("changed")),
                }
                for record in interactions
                if record.get("type") == "legal_expansion"
                and str(record.get("expanded_text", "")).strip()
            ]
            if role in {"agb", "privacy", "datenschutz"}:
                _write_json(
                    target_root / "expanded-legal-blocks.json",
                    {"blocks": expanded_blocks},
                )
            evidence_text = _merge_evidence_text(
                final_evidence_text,
                *(block["text"] for block in expanded_blocks),
            )
            normalized_text = "\n".join(
                line.strip() for line in evidence_text.splitlines() if line.strip()
            )
            visible_blocks = [line for line in evidence_text.splitlines() if line.strip()]
            included_blocks = [line for line in normalized_text.splitlines() if line.strip()]
            coverage_ratio = (
                len(included_blocks) / len(visible_blocks) if visible_blocks else 0.0
            )
            _write_text(target_root / "normalized-text.txt", normalized_text)
            _write_json(
                target_root / "clauses.json",
                {
                    "clauses": _simple_clauses(normalized_text),
                    "source": "visible-text-final_and_sequential_expansions",
                },
            )
            _write_json(
                target_root / "content-coverage.json",
                {
                    "method": "semantic_main_container_visible_text",
                    "normalized_visible_blocks": len(visible_blocks),
                    "included_blocks": len(included_blocks),
                    "coverage_ratio": coverage_ratio,
                    "omitted_blocks": [],
                    "legal_expansion": legal_expansion_summary,
                },
            )
            phase_durations["expansion"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())

            failure_phase = "screenshot"
            _wait_for_visual_capture(page, timeout_seconds=self.timeout_seconds)
            screenshot = _capture_validated_screenshots(page, target_root, interactions)
            if role in {"agb", "privacy", "datenschutz"}:
                _capture_expanded_legal_print_pdf(
                    page,
                    target_root,
                    legal_expansion_summary or {},
                    expanded_blocks,
                    normalized_text,
                )
            expansion_incomplete = bool(
                legal_expansion_summary
                and not legal_expansion_summary.get("complete", False)
            )
            if role in {"agb", "privacy", "datenschutz"} and (
                coverage_ratio < 0.98 or expansion_incomplete
            ):
                reason = (
                    f"Rechtstextabdeckung {coverage_ratio:.1%} liegt unter 98 %."
                    if coverage_ratio < 0.98
                    else "Nicht alle erkannten Rechtstext-Akkordeons konnten geöffnet werden."
                )
                screenshot = replace(
                    screenshot,
                    capture_state="page_content_truncated",
                    state_reason=reason,
                    capture_completeness="teilweise_erfasst",
                )
            phase_durations["screenshot"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())
            failure_phase = None
        except PlaywrightError as exc:
            failure_message = f"{type(exc).__name__}: {exc}"
            if not (initial and _browser_was_closed(exc)):
                raise ScreenshotCaptureError(
                    f"Browser-Abruf fehlgeschlagen in Phase {failure_phase}: {exc}"
                ) from exc
        except ScreenshotCaptureError as exc:
            failure_message = f"{type(exc).__name__}: {exc}"
            if initial is None:
                raise
        finally:
            try:
                if page is not None:
                    page.close()
            except PlaywrightError:
                pass
            finally:
                try:
                    if context is not None:
                        context.close()
                except PlaywrightError:
                    pass

        if initial is None:
            raise ScreenshotCaptureError("Kein Initialzustand konnte gesichert werden.")
        normalized_path = target_root / "normalized-text.txt"
        if not normalized_path.is_file():
            _write_text(normalized_path, _normalized_html_text(initial["dom"]))
        protection = _detect_block_page(initial["dom"])
        if protection:
            completeness = "durch_seitenschutz_begrenzt"
        elif failure_message or screenshot is None or not initial["raw_response"]:
            completeness = "teilweise_erfasst"
        else:
            completeness = screenshot.capture_completeness
        process_samples.append(_process_sample())
        rss_values = [
            int(sample["rss_bytes"])
            for sample in process_samples
            if isinstance(sample.get("rss_bytes"), int)
        ]
        handles = [
            int(sample["handles"])
            for sample in process_samples
            if isinstance(sample.get("handles"), int)
        ]
        stored_files = [path for path in target_root.rglob("*") if path.is_file()]
        metrics = {
            "duration_seconds": round(time.perf_counter() - phase_started, 6),
            "phase_durations_seconds": {
                key: round(max(0.0, value), 6) for key, value in phase_durations.items()
            },
            "python_rss_bytes": (
                {
                    "average": round(statistics.fmean(rss_values)),
                    "maximum": max(rss_values),
                    "samples": rss_values,
                }
                if rss_values
                else {"value": "not_available", "reason": "psutil lieferte keine RSS-Probe."}
            ),
            "python_cpu_time_seconds": {
                "start": {
                    "user": process_samples[0].get("cpu_user_seconds"),
                    "system": process_samples[0].get("cpu_system_seconds"),
                },
                "end": {
                    "user": process_samples[-1].get("cpu_user_seconds"),
                    "system": process_samples[-1].get("cpu_system_seconds"),
                },
            },
            "python_peak_handles_or_fds": max(handles) if handles else {
                "value": "not_available",
                "reason": "psutil lieferte keine Handle-/FD-Probe.",
            },
            "chromium_peak_rss_bytes": {
                "value": "not_available",
                "reason": "Playwright stellt unter Windows keine stabile Chromium-PID bereit.",
            },
            "requests_by_resource_type": request_counts,
            "transferred_bytes_from_content_length": transferred_bytes,
            "responses_without_content_length": transferred_unknown,
            "temporary_storage_bytes": sum(path.stat().st_size for path in stored_files),
            "raw_response_bytes": (target_root / "raw-response.bin").stat().st_size,
            "dom_initial_bytes": (target_root / "dom-initial.html").stat().st_size,
            "dom_final_bytes": (
                (target_root / "dom-after-expansion.html").stat().st_size
                if (target_root / "dom-after-expansion.html").is_file()
                else {"value": "not_available", "reason": "Browser endete vor dem Finalzustand."}
            ),
            "browser_starts": self.browser_starts,
            "contexts": self.contexts,
            "pages": self.pages,
            "failure_phase": failure_phase,
            "failure_message": failure_message,
        }
        metrics_path = target_root / "resource-metrics.json"
        _write_json(metrics_path, metrics)
        _write_json(target_root / "interactions.json", {"interactions": interactions})
        browser_metadata = {
            "erfassungsmodus": "browsergestuetzt",
            "user_agent": initial["user_agent"],
            "navigator_webdriver": initial["navigator_webdriver"],
            "automation_flags": [],
            "proxy": "keiner",
            "context": "frisch_pro_ziel_url",
            "storage_state": "keiner",
            "profilverzeichnis": "keines",
            "browser_engine": "Chromium",
            "browser_version": self._browser.version,
            "launch_args": list(self.launch_args),
            "request_count": sum(request_counts.values()),
            "document_request_count": request_counts.get("document", 0),
            "blocked_request_count": len(blocked_requests),
            "capture_artifact_directory": str(target_root),
            "capture_completeness": completeness,
            "failure_phase": failure_phase,
            "failure_message": failure_message,
        }
        _write_json(target_root / "browser-metadata.json", browser_metadata)
        headers = tuple(initial["headers"].items()) + (
            ("X-MucLegal-Capture-Mode", "browser-rendered-dom"),
        )
        fetch_result = FetchResult(
            requested_url=url,
            final_url=initial["final_url"],
            fetched_at=initial["captured_at"],
            status_code=int(initial["status_code"]),
            headers=headers,
            redirect_chain=tuple(initial["redirect_chain"]),
            body=initial["dom"].encode("utf-8"),
            decoded_html=initial["dom"],
            fetch_mode="browser_review",
            browser_metadata=browser_metadata,
        )
        return BrowserTargetCapture(
            fetch_result=fetch_result,
            screenshot=screenshot,
            artifact_directory=str(target_root),
            capture_completeness=completeness,
            failure_phase=failure_phase,
        )


def _capture_initial_state(page, response, requested_url: str) -> dict:  # noqa: ANN001
    redirect_chain: list[str] = []
    redirected_request = response.request
    while redirected_request.redirected_from is not None:
        redirect_chain.append(redirected_request.url)
        redirected_request = redirected_request.redirected_from
    redirect_chain.reverse()
    try:
        raw_response = response.body()
        raw_response_source = "playwright_document_response_body"
    except Exception as exc:
        raw_response = b""
        raw_response_source = f"not_available:{type(exc).__name__}:{exc}"
    snapshot = page.evaluate(
        """() => ({
          title: document.title,
          dom: document.documentElement?.outerHTML || '',
          visibleText: document.body?.innerText || '',
          userAgent: navigator.userAgent,
          navigatorWebdriver: navigator.webdriver,
          viewport: {width: window.innerWidth, height: window.innerHeight},
          scrollWidth: document.documentElement?.scrollWidth || 0,

item.formatted_output:
    )
    return privacy_terms >= 2 and len(text) >= 1_500


def _bundle_browser_capture_artifacts(
    *,
    bundle: Path,
    artifacts_dir: Path,
    bundled_artifacts: dict[str, Path],
    role_captures: dict[str, ScreenshotCapture | None],
    legal_screenshot_statuses: dict[str, dict[str, str]],
    protection_type: str | None,
    requested_url: str,
    captured_url: str,
    browser_run_root: str | None,
) -> tuple[str, dict[str, dict[str, Any]], Path]:
    entries: list[dict[str, Any]] = []
    galleries: dict[str, dict[str, Any]] = {}
    metric_documents: list[dict[str, Any]] = []
    copied_directories: dict[str, str] = {}
    page_artifacts: dict[str, dict[str, Any]] = {}
    for role, capture in role_captures.items():
        if capture is None or not getattr(capture, "artifact_directory", None):
            continue
        source_root = Path(capture.artifact_directory).resolve()
        source_key = str(source_root)
        effective_role = copied_directories.get(source_key, role)
        if source_key not in copied_directories:
            role_root = artifacts_dir / "roles" / role
            shutil.copytree(source_root, role_root)
            copied_directories[source_key] = role
            for path in sorted(role_root.rglob("*")):
                if not path.is_file():
                    continue
                relative = path.relative_to(bundle).as_posix()
                relative_in_role = path.relative_to(role_root).as_posix()
                label = f"capture_{role}_{relative_in_role}"
                bundled_artifacts[label] = path
                entries.append(
                    {
                        "role": role,
                        "path": relative,
                        "sha256": sha256_file(path),
                        "size_bytes": path.stat().st_size,
                        "kind": (
                            "derived_preview"
                            if path.name == "screenshot-preview.webp" else "original"
                        ),
                        "derived_from": (
                            f"artifacts/roles/{role}/screenshot-index.json"
                            if path.name == "screenshot-preview.webp" else None
                        ),
                    }
                )
            resource_metrics = role_root / "resource-metrics.json"
            if resource_metrics.is_file():
                metric_documents.append(
                    json.loads(resource_metrics.read_text(encoding="utf-8"))
                )
        role_root = artifacts_dir / "roles" / effective_role
        screenshot_index = role_root / "screenshot-index.json"
        page_record = _page_artifact_record(bundle, role_root, role, effective_role)
        page_artifacts[role] = page_record
        if screenshot_index.is_file():
            index_data = json.loads(screenshot_index.read_text(encoding="utf-8"))
            galleries[role] = {
                "source_role": effective_role,
                "preview": f"artifacts/roles/{effective_role}/screenshot-preview.webp",
                "index": f"artifacts/roles/{effective_role}/screenshot-index.json",
                "mode": index_data.get("mode"),
                "capture_completeness": index_data.get("capture_completeness"),
                "tiles": [
                    f"artifacts/roles/{effective_role}/{item['path']}"
                    for item in index_data.get("tiles", [])
                ],
                "originals": (
                    [f"artifacts/roles/{effective_role}/screenshot-full-page.png"]
                    if index_data.get("full_page_attempt", {}).get("path")
                    else []
                ),
                "raw_html": page_record["primary_raw_html"],
                "normalized_text": page_record["primary_normalized_text"],
                "documents": [
                    item["path"] for item in page_record["document_files"]
                ],
                "page_artifacts_complete": page_record["required_artifacts_complete"],
            }
    page_artifacts_index = artifacts_dir / "page-artifacts-index.json"
    _write_json(
        page_artifacts_index,
        {
            "version": 1,
            "scope": "jede_im_lauf_tatsaechlich_erfasste_seite",
            "pages": page_artifacts,
            "all_required_artifacts_complete": all(
                item["required_artifacts_complete"] for item in page_artifacts.values()
            ) if page_artifacts else False,
        },
    )
    bundled_artifacts["page_artifacts_index"] = page_artifacts_index
    states = [
        getattr(capture, "capture_completeness", "vollstaendig_erfasst")
        for capture in role_captures.values()
        if capture is not None
    ]
    if protection_type:
        completeness = "durch_seitenschutz_begrenzt"
    elif role_captures.get("main") is None:
        completeness = "teilweise_erfasst"
    elif "teilweise_erfasst" in states or any(
        status.get("status") in {"failed", "warning"}
        for status in legal_screenshot_statuses.values()
    ) or any(
        not item["required_artifacts_complete"] for item in page_artifacts.values()
    ):
        completeness = "teilweise_erfasst"
    else:
        completeness = "vollstaendig_erfasst"
    capture_index = artifacts_dir / "capture-index.json"
    _write_json(
        capture_index,
        {
            "version": 1,
            "capture_completeness": completeness,
            "sources": galleries,
            "artifacts": entries,
        },
    )
    bundled_artifacts["capture_index"] = capture_index
    metrics_path = artifacts_dir / "capture-metrics.json"
    _write_json(
        metrics_path,
        {
            "version": 1,
            "targets": metric_documents,
            "browser_run_root": browser_run_root,
            "warc_size_bytes": {"value": "pending", "reason": "WARC folgt."},
            "zip_size_bytes": {
                "value": "not_available",
                "reason": "ZIP wird erst beim lokalen Download erzeugt.",
            },
        },
    )
    bundled_artifacts["capture_metrics"] = metrics_path
    run_result = artifacts_dir / "run-result.json"
    _write_json(
        run_result,
        {
            "status": completeness,
            "requested_url": requested_url,
            "captured_url": captured_url,
            "protection_type": protection_type,
            "failure_phase": next(
                (
                    document.get("failure_phase")
                    for document in metric_documents
                    if document.get("failure_phase")
                ),
                None,
            ),
            "available_intermediate_artifacts": [item["path"] for item in entries],
        },
    )
    bundled_artifacts["run_result"] = run_result
    return completeness, galleries, metrics_path


def _page_artifact_record(
    bundle: Path,
    role_root: Path,
    role: str,
    source_role: str,
) -> dict[str, Any]:
    """Inventory HTML, normalized text and every image for one captured page."""
    request_path = role_root / "request.json"
    request_data = (
        failure_message: str | None = None
        screenshot: ScreenshotCapture | None = None
        context = None
        page = None
        try:
            context = self._browser.new_context(
                viewport={"width": 1440, "height": 900},
                user_agent=self.user_agent,
                locale="de-DE",
            )
            self.contexts += 1

            def route_request(route) -> None:  # noqa: ANN001
                browser_request = route.request
                resource_type = browser_request.resource_type
                request_counts[resource_type] = request_counts.get(resource_type, 0) + 1
                if browser_request.method.upper() not in {"GET", "HEAD", "OPTIONS"}:
                    blocked_requests.append({"url": browser_request.url, "reason": "method"})
                    route.abort()
                    return
                try:
                    if self.request_guard is not None:
                        self.request_guard(browser_request.url, resource_type)
                except Exception as exc:
                    blocked_requests.append({"url": browser_request.url, "reason": str(exc)})
                    route.abort()
                    return
                route.continue_()

            def record_response(response) -> None:  # noqa: ANN001
                nonlocal transferred_bytes, transferred_unknown
                try:
                    value = response.headers.get("content-length")
                    if value and value.isdigit():
                        transferred_bytes += int(value)
                    else:
                        transferred_unknown += 1
                except PlaywrightError:
                    transferred_unknown += 1

            context.route("**/*", route_request)
            page = context.new_page()
            self.pages += 1
            page.on("response", record_response)
            failure_phase = "navigation_domcontentloaded"
            navigation_started = time.perf_counter()
            response = page.goto(
                url,
                wait_until="domcontentloaded",
                timeout=int(self.timeout_seconds * 1000),
            )
            phase_durations["navigation_domcontentloaded"] = time.perf_counter() - navigation_started
            if response is None:
                raise ScreenshotCaptureError("Browsernavigation lieferte keine HTTP-Antwort.")
            failure_phase = "initialzustand_sichern"
            initial = _capture_initial_state(page, response, url)
            _write_initial_artifacts(target_root, initial)
            process_samples.append(_process_sample())
            if self.after_initial_hook is not None:
                self.after_initial_hook(page, target_root)
            phase_durations["initialzustand_sichern"] = (
                time.perf_counter() - navigation_started
                - phase_durations["navigation_domcontentloaded"]
            )
            if int(initial["status_code"]) >= 400:
                raise ScreenshotCaptureError(
                    f"Browsernavigation endete mit HTTP {initial['status_code']}."
                )

            failure_phase = "consent"
            consent = handle_consent(
                page, str(target_root / "screenshot-before-consent.png")
            )
            interactions.append(consent)
            _write_text(target_root / "dom-after-consent.html", page.content())
            _write_text(
                target_root / "visible-text-after-consent.txt", _visible_text(page)
            )
            phase_durations["consent"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())

            failure_phase = "expansion"
            legal_expansion_summary: dict[str, object] | None = None
            if role in {"agb", "privacy", "datenschutz"}:
                expansion_records = _expand_legal_controls(page)
                interactions.extend(expansion_records)
                legal_expansion_summary = _legal_expansion_summary(
                    page, expansion_records
                )
            _write_text(target_root / "dom-after-expansion.html", page.content())
            final_text = _visible_text(page)
            _write_text(target_root / "visible-text-final.txt", final_text)
            final_evidence_text = (
                _legal_container_text(page)
                if role in {"agb", "privacy", "datenschutz"}
                else final_text
            )
            expanded_blocks = [
                {
                    "target_text": str(record.get("target_text", "")),
                    "aria_controls": record.get("aria_controls"),
                    "text": str(record.get("expanded_text", "")),
                    "changed": bool(record.get("changed")),
                }
                for record in interactions
                if record.get("type") == "legal_expansion"
                and str(record.get("expanded_text", "")).strip()
            ]
            if role in {"agb", "privacy", "datenschutz"}:
                _write_json(
                    target_root / "expanded-legal-blocks.json",
                    {"blocks": expanded_blocks},
                )
            evidence_text = _merge_evidence_text(
                final_evidence_text,
                *(block["text"] for block in expanded_blocks),
            )
            normalized_text = "\n".join(
                line.strip() for line in evidence_text.splitlines() if line.strip()
            )
            visible_blocks = [line for line in evidence_text.splitlines() if line.strip()]
            included_blocks = [line for line in normalized_text.splitlines() if line.strip()]
            coverage_ratio = (
                len(included_blocks) / len(visible_blocks) if visible_blocks else 0.0
            )
            _write_text(target_root / "normalized-text.txt", normalized_text)
            _write_json(
                target_root / "clauses.json",
                {
                    "clauses": _simple_clauses(normalized_text),
                    "source": "visible-text-final_and_sequential_expansions",
                },
            )
            _write_json(
                target_root / "content-coverage.json",
                {
                    "method": "semantic_main_container_visible_text",
                    "normalized_visible_blocks": len(visible_blocks),
                    "included_blocks": len(included_blocks),
                    "coverage_ratio": coverage_ratio,
                    "omitted_blocks": [],
                    "legal_expansion": legal_expansion_summary,
                },
            )
            phase_durations["expansion"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())

            failure_phase = "screenshot"
            _wait_for_visual_capture(page, timeout_seconds=self.timeout_seconds)
            screenshot = _capture_validated_screenshots(page, target_root, interactions)
            if role in {"agb", "privacy", "datenschutz"}:
                _capture_expanded_legal_print_pdf(
                    page,
                    target_root,
                    legal_expansion_summary or {},
                    expanded_blocks,
                    normalized_text,
                )
            expansion_incomplete = bool(
                legal_expansion_summary
                and not legal_expansion_summary.get("complete", False)
            )
            if role in {"agb", "privacy", "datenschutz"} and (
                coverage_ratio < 0.98 or expansion_incomplete
            ):
                reason = (
                    f"Rechtstextabdeckung {coverage_ratio:.1%} liegt unter 98 %."
                    if coverage_ratio < 0.98
                    else "Nicht alle erkannten Rechtstext-Akkordeons konnten geöffnet werden."
                )
                screenshot = replace(
                    screenshot,
                    capture_state="page_content_truncated",
                    state_reason=reason,
                    capture_completeness="teilweise_erfasst",
                )
            phase_durations["screenshot"] = time.perf_counter() - navigation_started - sum(
                phase_durations.values()
            )
            process_samples.append(_process_sample())
            failure_phase = None
        except PlaywrightError as exc:
            failure_message = f"{type(exc).__name__}: {exc}"
            if not (initial and _browser_was_closed(exc)):
                raise ScreenshotCaptureError(
                    f"Browser-Abruf fehlgeschlagen in Phase {failure_phase}: {exc}"
                ) from exc
        except ScreenshotCaptureError as exc:
            failure_message = f"{type(exc).__name__}: {exc}"
            if initial is None:
                raise
        finally:
            try:
                if page is not None:
                    page.close()
            except PlaywrightError:
                pass
            finally:
                try:
                    if context is not None:
                        context.close()
                except PlaywrightError:
                    pass

        if initial is None:
            raise ScreenshotCaptureError("Kein Initialzustand konnte gesichert werden.")
        normalized_path = target_root / "normalized-text.txt"
        if not normalized_path.is_file():
            _write_text(normalized_path, _normalized_html_text(initial["dom"]))
        protection = _detect_block_page(initial["dom"])
        if protection:
            completeness = "durch_seitenschutz_begrenzt"
        elif failure_message or screenshot is None or not initial["raw_response"]:
            completeness = "teilweise_erfasst"
        else:
            completeness = screenshot.capture_completeness
        process_samples.append(_process_sample())
        rss_values = [
            int(sample["rss_bytes"])
            for sample in process_samples
            if isinstance(sample.get("rss_bytes"), int)
        ]
        handles = [
            int(sample["handles"])
            for sample in process_samples
            if isinstance(sample.get("handles"), int)
        ]
        stored_files = [path for path in target_root.rglob("*") if path.is_file()]
        metrics = {
            "duration_seconds": round(time.perf_counter() - phase_started, 6),
            "phase_durations_seconds": {
                key: round(max(0.0, value), 6) for key, value in phase_durations.items()
            },
            "python_rss_bytes": (
                {
                    "average": round(statistics.fmean(rss_values)),
                    "maximum": max(rss_values),
                    "samples": rss_values,
                }
                if rss_values
                else {"value": "not_available", "reason": "psutil lieferte keine RSS-Probe."}
            ),
            "python_cpu_time_seconds": {
                "start": {
                    "user": process_samples[0].get("cpu_user_seconds"),
                    "system": process_samples[0].get("cpu_system_seconds"),
                },
                "end": {
                    "user": process_samples[-1].get("cpu_user_seconds"),
                    "system": process_samples[-1].get("cpu_system_seconds"),
                },
            },
            "python_peak_handles_or_fds": max(handles) if handles else {
                "value": "not_available",
                "reason": "psutil lieferte keine Handle-/FD-Probe.",
            },
            "chromium_peak_rss_bytes": {
                "value": "not_available",
                "reason": "Playwright stellt unter Windows keine stabile Chromium-PID bereit.",
            },
            "requests_by_resource_type": request_counts,
            "transferred_bytes_from_content_length": transferred_bytes,
            "responses_without_content_length": transferred_unknown,
            "temporary_storage_bytes": sum(path.stat().st_size for path in stored_files),
            "raw_response_bytes": (target_root / "raw-response.bin").stat().st_size,
            "dom_initial_bytes": (target_root / "dom-initial.html").stat().st_size,
            "dom_final_bytes": (
                (target_root / "dom-after-expansion.html").stat().st_size
                if (target_root / "dom-after-expansion.html").is_file()
                else {"value": "not_available", "reason": "Browser endete vor dem Finalzustand."}
            ),
            "browser_starts": self.browser_starts,
            "contexts": self.contexts,
            "pages": self.pages,
            "failure_phase": failure_phase,
            "failure_message": failure_message,
        }
        metrics_path = target_root / "resource-metrics.json"
        _write_json(metrics_path, metrics)
        _write_json(target_root / "interactions.json", {"interactions": interactions})
        browser_metadata = {
            "erfassungsmodus": "browsergestuetzt",
