    def _try_public_legal_subpages(
        self,
        protected_url: str,
        protection_type: str,
        progress: ProgressCallback,
        browser_mode: bool,
        blocked_source_url: str,
        blocked_source_type: str,
        god_mode: bool = False,
    ) -> LiveWorkflowResult:
