    .lab-link:hover { background:var(--muted-bg); }
    .sidebar-toggle { display:none; }
    .workspace { min-height:0; display:grid; grid-template-columns:minmax(0,1.62fr) minmax(360px,1fr); }
    .control { min-height:0; overflow:hidden; padding:clamp(10px,1.6vh,18px) clamp(12px,1.6vw,24px); display:flex; flex-direction:column; gap:clamp(8px,1.25vh,14px); }
    .control.intake-mode { overflow-y:auto; overscroll-behavior:contain; scrollbar-gutter:stable; }
    .proof { min-height:0; overflow-y:auto; overscroll-behavior:contain; scrollbar-gutter:stable; background:#fff; border-left:1px solid var(--border); }
    .proof-inner { min-height:100%; padding:clamp(12px,1.6vw,22px); }
    .card { border:1px solid var(--border); border-radius:var(--radius); background:var(--card); box-shadow:var(--shadow); }
    .card-pad { padding:clamp(10px,1.4vh,16px); }
    h1,h2,h3,p { margin:0; }
    h1 { font-size:clamp(16px,1.45vw,20px); letter-spacing:-.02em; }
    h2 { font-size:13px; }
    h3 { color:var(--muted); font-size:10px; font-weight:700; letter-spacing:.08em; text-transform:uppercase; }
    .muted { color:var(--muted); }
    .url-head { display:flex; justify-content:space-between; gap:14px; align-items:flex-start; }
    .url-head p { margin-top:2px; max-width:670px; font-size:11px; }
    .url-form { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:8px; margin-top:10px; }
    .tenor-panel summary { cursor:pointer; font-weight:700; }
    .tenor-grid { display:grid; grid-template-columns:1fr 1fr; gap:7px; margin-top:9px; }
