    .review .button { height:30px; padding:0 9px; font-size:10px; }
    .proof-head { position:sticky; top:0; z-index:3; margin:-1px -1px 0; padding:0 1px 12px; background:#fff; }
    .proof-title { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; }
    .proof-title p { margin-top:2px; font-size:11px; color:var(--muted); }
    .selectors { display:grid; grid-template-columns:1fr 1fr; gap:7px; margin-top:10px; }
    .select { height:34px; font-size:11px; }
    .proof-summary { margin-bottom:12px; padding:10px; background:var(--muted-bg); box-shadow:none; }
    .summary-url { overflow:hidden; margin-bottom:8px; font-size:11px; font-weight:650; text-overflow:ellipsis; white-space:nowrap; }
    .summary-grid { display:grid; grid-template-columns:1fr 1fr; gap:5px 10px; font-size:10px; }
    .summary-grid span { color:var(--muted); }
    .summary-grid strong { display:block; overflow:hidden; color:var(--foreground); text-overflow:ellipsis; white-space:nowrap; }
    .artifact-group { margin-top:12px; }
    .artifact-group h3 { margin-bottom:6px; }
    .artifact-list { display:grid; grid-template-columns:1fr 1fr; gap:5px; }
    .artifact { display:flex; align-items:center; gap:7px; min-width:0; border:1px solid var(--border); border-radius:calc(var(--radius) - 3px); background:#fff; padding:7px 8px; color:var(--foreground); text-align:left; cursor:pointer; }
    .artifact:hover:not(:disabled),.artifact.selected { border-color:#67e8f9; background:#ecfeff; }
    .artifact:disabled { color:#94a3b8; background:#f8fafc; cursor:default; }
    .artifact-mark { flex:0 0 auto; width:7px; height:7px; border-radius:50%; background:var(--success); }
    .artifact:disabled .artifact-mark { background:#cbd5e1; }
    .artifact span:last-child { overflow:hidden; font-size:10px; font-weight:650; text-overflow:ellipsis; white-space:nowrap; }
    .preview { margin-top:12px; overflow:hidden; }
    .preview-bar { display:flex; align-items:center; gap:8px; min-height:34px; padding:7px 9px; border-bottom:1px solid var(--border); }
    .preview-bar strong { overflow:hidden; margin-right:auto; font-size:10px; text-overflow:ellipsis; white-space:nowrap; }
    .preview-bar a { color:var(--primary); font-size:10px; font-weight:650; text-decoration:none; }
    .preview-empty { display:grid; min-height:150px; place-items:center; padding:20px; color:var(--muted); text-align:center; }
    pre { max-height:330px; min-height:150px; margin:0; overflow:auto; padding:11px; background:#0f172a; color:#dbeafe; font:10px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace; white-space:pre-wrap; word-break:break-word; }
    .pdf-frame { width:100%; height:430px; border:0; background:var(--muted-bg); }
    .image-preview { display:block; width:100%; max-height:520px; object-fit:contain; background:var(--muted-bg); }
    [hidden] { display:none !important; }
    @media (max-height:800px) {
      .brand-copy span,.url-head p { display:none; }
      .control { gap:7px; padding-top:8px; padding-bottom:8px; }
      .card-pad,.pipeline-card,.metric-card { padding:9px; }
      .url-form { margin-top:7px; }
      .alert { margin-top:6px; padding:5px 8px; }
      .step { padding:5px 3px; }
      .metric-list { gap:5px; padding-top:6px; }
      .review { padding-top:6px; padding-bottom:6px; }
    }
    @media (max-width:1023px) {
      .workspace { display:block; }
      .control { height:100%; }
      .proof { position:fixed; z-index:20; inset:clamp(54px,7.2vh,66px) 0 0 auto; width:min(92vw,480px); border-left:1px solid var(--border); box-shadow:-16px 0 40px rgb(15 23 42 / .16); transform:translateX(102%); transition:transform .2s ease; }
      .proof.open { transform:translateX(0); }
      .sidebar-toggle { display:inline-flex; }
    }
