                value += 35
            if "allgemeine geschäftsbedingungen" in label:
                value += 30
            if "/terms" in url or "/agb" in url:
                value += 12
        else:
            if label.strip() in {"datenschutz", "datenschutzerklärung", "datenschutzhinweise"}:
                value += 35
            if "datenschutzerklärung" in label:
                value += 28
