    def normalized(value: str) -> tuple[str, str, str, str]:
        parsed = urlsplit(value)
        path = parsed.path.rstrip("/") or "/"
        return parsed.scheme.lower(), parsed.netloc.lower(), path, parsed.query

    return normalized(left) == normalized(right)


