                    "method": "semantic_main_container_visible_text",
                    "normalized_visible_blocks": len(visible_blocks),
                    "included_blocks": len(included_blocks),
                    "coverage_ratio": coverage_ratio,
                    "omitted_blocks": [],
                    "legal_expansion": legal_expansion_summary,
