                "status": "failed",
                "reason": f"{type(exc).__name__}: {exc}",
                "website_original": False,
                "expansion_summary": expansion_summary,
            },
        )


def _capture_validated_screenshots(page, root: Path, interactions: list[dict]) -> ScreenshotCapture:  # noqa: ANN001
