            try:
                record = self._read(case_path)
            except (OSError, ValueError, json.JSONDecodeError):
                continue
            cases.append(self._summary(case_path.parent.name, record))
        return sorted(cases, key=lambda item: item["erkannt_am"], reverse=True)

